using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.UIElements;

namespace ZERO
{
    /// <summary>References to everything generated by the editor build script (materials keep the shaders in the build).</summary>
    public class GameAssets : ScriptableObject
    {
        public Material Sky, Earth, Cloud, Cabin, Glass;
        public Material Asteroid, Plasma, Trail;
        public Material Fireball, Dome, Smoke, Streak, Ribbon, Glow;
        public Material Fullscreen, Beam;
        public PanelSettings Panel;
        public VolumeProfile Volume;
        public static GameAssets I;
    }
}
